// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[대상 IP 추출] ' + s);
};
// ───────────────────────────────────────────────────────────
// [롤백] 잘못 내려간 차단을 되돌린다.
// 파급이 큰 액션에는 반드시 되돌리는 경로를 함께 만들어 둔다.
const b = $json.body ?? $json;
L('롤백 요청 수신:', b);
if (!b.ip) L('!! ip 가 비어 있다 — 요청 본문을 확인할 것');
L(`대상 ${b.ip} 의 차단을 해제한다`);
return [{ json: { ip: b.ip, reason: b.reason ?? '오탐 확인 — 차단 해제', _log } }];

// ── 로그 헬퍼 ───────────────────────────────────────────────
// L(...) 로 남긴 기록은 두 곳에서 보인다.
//   1) 편집 화면에서 이 노드를 실행하면  → 출력 패널의 'Logs' 탭 (console.log)
//   2) 모든 실행 (프로덕션 포함)         → 출력 데이터의 _log 필드
const _log = [];
const L = (...a) => {
  const s = a.map(v => (typeof v === 'object' ? JSON.stringify(v) : String(v))).join(' ');
  _log.push(s);
  console.log('[차단 해제] ' + s);
};
// ───────────────────────────────────────────────────────────
const res = $json;
L('방화벽 응답:', res);
L(res.removed ? `→ ${res.removed.ip} 차단 해제 완료` : '→ 차단 목록에 없던 IP 다 (멱등 — 재시도해도 안전)');
return [{ json: { ...res, _log: [ ...(res._log || []), ..._log ] } }];
